test("render shell pure helpers: build zero-import Wasm", () => {
  exp = loadExports();
  assert.equal(exp.isaac_render_shell_pure_helpers_abi_version(), 74);
  assert.equal(RENDER_SHELL_PURE_ABI_VERSION, 74);
});

test("G0 main_body_needed fixed cases", () => {
  assert.equal(renderShellMainBodyNeeded(0), false);
  assert.equal(renderShellMainBodyNeeded(1), true);
  assert.equal(renderShellMainBodyNeeded(0xff), true);
  assert.equal(exp.isaac_render_shell_main_body_needed(0), 0);
  assert.equal(exp.isaac_render_shell_main_body_needed(1), 1);
  assert.equal(exp.isaac_render_shell_main_body_needed(0x2a), 1);
});

test("G1 manager_fade_poll_needed fixed cases (comiss/ja)", () => {
  const cases = [
    { v: 0, need: true },
    { v: -1, need: true },
    { v: -0, need: true },
    { v: 0.0001, need: false },
    { v: 1, need: false },
    { v: Number.NaN, need: true },
    { v: Number.POSITIVE_INFINITY, need: false },
    { v: Number.NEGATIVE_INFINITY, need: true },
  ];
  for (const c of cases) {
    assert.equal(
      renderShellManagerFadePollNeeded(c.v),
      c.need,
      `oracle fade=${c.v}`,
    );
    assert.equal(
      exp.isaac_render_shell_manager_fade_poll_needed(c.v) !== 0,
      c.need,
      `wasm fade=${c.v}`,
    );
  }
});

