  assert.equal(renderShell409120FramePtr(0x1000, 1) >>> 0, 0x106c);
  assert.equal(renderShell409120FramePtr(0x1000, 2) >>> 0, 0x10d8);
  assert.equal(exp.isaac_render_shell_409120_frame_ptr(0x1000, 2) >>> 0, 0x10d8);

  /* G121 frame visible */
  assert.equal(renderShell409120FrameVisible(0), false);
  assert.equal(renderShell409120FrameVisible(1), true);
  assert.equal(exp.isaac_render_shell_409120_frame_visible(0), 0);
