test("G13 aux 817830 nested decision + G8 composite", () => {
  /* fade > 0 → poll not needed → call direct */
  assert.equal(renderShellAux817830Needed(false, false), true);
  assert.equal(renderShellAux817830Needed(false, true), true);
  /* poll path: only when selects_one */
  assert.equal(renderShellAux817830Needed(true, false), false);
  assert.equal(renderShellAux817830Needed(true, true), true);
  assert.equal(exp.isaac_render_shell_aux_817830_needed(0, 0), 1);
  assert.equal(exp.isaac_render_shell_aux_817830_needed(1, 0), 0);
  assert.equal(exp.isaac_render_shell_aux_817830_needed(1, 1), 1);

  /* option closed always skips */
  assert.equal(renderShellOptionAux817830Needed(0, false, true), false);
  assert.equal(renderShellOptionAux817830Needed(0, true, true), false);
  assert.equal(renderShellOptionAux817830Needed(1, false, false), true);
  assert.equal(renderShellOptionAux817830Needed(1, true, false), false);
  assert.equal(renderShellOptionAux817830Needed(1, true, true), true);
  assert.equal(exp.isaac_render_shell_option_aux_817830_needed(0, 0, 1), 0);
  assert.equal(exp.isaac_render_shell_option_aux_817830_needed(1, 0, 0), 1);
  assert.equal(exp.isaac_render_shell_option_aux_817830_needed(1, 1, 0), 0);
  assert.equal(exp.isaac_render_shell_option_aux_817830_needed(2, 1, 1), 1);

  /* end-to-end PE shape: fade>0 and option on → call without poll results */
  assert.equal(
    renderShellOptionAux817830Needed(
      1,
      renderShellManagerFadePollNeeded(0.5),
      false,
    ),
    true,
  );
  /* fade<=0 / NaN → poll path; bit clear → skip */
  assert.equal(
    renderShellOptionAux817830Needed(
      1,
      renderShellManagerFadePollNeeded(0),
      renderShellFadePollSelectsOne(0, 0, 0xffffffff),
    ),
    false,
  );
  /* fade<=0 with select bit → call */
  assert.equal(
    renderShellOptionAux817830Needed(
      1,
      renderShellManagerFadePollNeeded(0),
      renderShellFadePollSelectsOne(0, 1, 0),
    ),
    true,
  );
});

