test("817830 G18/G19 body continue + composite", () => {
  assert.equal(renderShell817830BodyContinueNeeded(0.5, false), true);
  assert.equal(renderShell817830BodyContinueNeeded(0, true), true);
  assert.equal(renderShell817830BodyContinueNeeded(0, false), false);
  assert.equal(renderShell817830BodyContinueNeeded(-1, false), false);
  assert.equal(renderShell817830BodyContinueNeeded(Number.NaN, false), false);
  assert.equal(renderShell817830BodyContinueNeeded(Number.NaN, true), true);
  assert.equal(exp.isaac_render_shell_817830_body_continue_needed(0.5, 0), 1);
  assert.equal(exp.isaac_render_shell_817830_body_continue_needed(0, 0), 0);
  assert.equal(exp.isaac_render_shell_817830_body_continue_needed(0, 1), 1);

  /* slot closed → never */
  assert.equal(renderShell817830BodyNeeded(0, 4, 0, 0x20, 1.0), false);
  /* slot open, fade>0 → yes without special */
  assert.equal(renderShell817830BodyNeeded(1, 0, -1, 0, 0.1), true);
  /* slot open, fade<=0, special → yes */
  assert.equal(renderShell817830BodyNeeded(1, 4, 0, 0x20, 0), true);
  /* slot open, fade<=0, not special → no */
  assert.equal(renderShell817830BodyNeeded(1, 0, 0, 0x20, 0), false);
  assert.equal(exp.isaac_render_shell_817830_body_needed(0, 4, 0, 0x20, 1), 0);
  assert.equal(exp.isaac_render_shell_817830_body_needed(1, 0, -1, 0, 0.1), 1);
  assert.equal(exp.isaac_render_shell_817830_body_needed(1, 4, 0, 0x20, 0), 1);
  assert.equal(exp.isaac_render_shell_817830_body_needed(1, 0, 0, 0x20, 0), 0);
});

