    /* ABI v16 812d00 + 4217a0 pure bodies */
    const f4z = rnd() & 1;
    const nestNz = rnd() & 1;
    const roomType812 = (rnd() % 16) | 0;
    const roomWidth812 = ((rnd() % 15) + 1) | 0; /* non-zero for idiv */
