/* Independent PE-truth reference for the vec18 magic division: the PE
   does span = (end-begin) WRAP-U32 then SIGN-magic-div-by-0x18 with
   C-truncation semantics (the +sign-fixup converts floor to trunc). */
function a149a0Vec18Ref(begin, end) {
  const span = (end - begin) >>> 0;
  const s = span < 0x80000000 ? span : span - 0x100000000;
  return Math.trunc(s / 24) || 0; /* PE result is an integer: no -0 */
}
function a149a0InnerCountRef(beginPtr, endPtr) {
  const diff = (endPtr - beginPtr) >>> 0;
  return ((diff | 0) >> 2) || 0;
}

