  assert.equal(RENDER_SHELL_A180A0_ADDR_TAKEN_COUNT, 0x1);
  assert.equal(RENDER_SHELL_A180A0_EAX_WRITES, 0x2);
  assert.equal(RENDER_SHELL_A180A0_STACK_ARGS, 0x0);
  assert.equal(RENDER_SHELL_A180A0_VTABLE_VA, 0xb82430);
