  assert.equal(RENDER_SHELL_A180A0_GS_COOKIE_VA, 0xbf93b4);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE1_NAME_VA, 0xb81e50);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE1_ARG2, 0xc0f8c0);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE1_BASE_VA, 0xb81f10);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE1_VAL, 0xca);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE1_STR_VA, 0xb820f8);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE1_VAL2, 0x9a);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE2_NAME_VA, 0xb1a5b0);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE2_ARG2, 0xc0f8f0);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE2_BASE_VA, 0xb81fe0);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE2_VAL, 0x117);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE2_STR_VA, 0xb82320);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE2_VAL2, 0x10b);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE3_NAME_VA, 0xb81940);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE3_ARG2, 0xc0f8f0);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE3_BASE_VA, 0xb81fe0);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE3_VAL, 0x117);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE3_STR_VA, 0xb82198);
  assert.equal(RENDER_SHELL_A180A0_TRIPLE3_VAL2, 0x186);
  assert.equal(RENDER_SHELL_A180A0_VT_SLOT_78, 0x78);
  assert.equal(RENDER_SHELL_A180A0_VT_SLOT_18, 0x18);
  assert.equal(RENDER_SHELL_A180A0_VT_SLOT_58, 0x58);
