  assert.equal(RENDER_SHELL_A180A0_NEXT_VA - RENDER_SHELL_A180A0_END_VA, 0x07);
  /* Independent PE-truth ref transcribed branch-by-branch
     (0xa1818b test eax,eax / 0xa1818d je 0xa18198). */
  const refAllocGate = (a) => (a >>> 0) !== 0 ? 1 : 0;
  const gateRows = [0, 1, 0x100, 0xffffffff];
