  assert.equal(renderShellA182c0FlagsSet(0), 8);
  assert.equal(renderShellA182c0FlagsSet(0xf0), 0xf8);
  assert.equal(exp.isaac_render_shell_a182c0_flags_clear(0) >>> 0, 0);
