  assert.equal(RENDER_SHELL_A1A540_CALLER_COUNT, 15);
  assert.equal(RENDER_SHELL_A1A540_CALLER_FIRST_VA, 0x430656);
  assert.equal(RENDER_SHELL_A1A540_CALLER_LAST_VA, 0x9b8312);
  assert.equal(RENDER_SHELL_A1A580_CALLER_COUNT, 6);
  assert.equal(RENDER_SHELL_A1A580_CALLER_FIRST_VA, 0x6fc4b1);
  assert.equal(RENDER_SHELL_A1A580_CALLER_LAST_VA, 0x9c53bb);
