  assert.equal(RENDER_SHELL_HOST_A1A2E0_CALLER_FIRST_VA, 0x925d0e);
  assert.equal(RENDER_SHELL_HOST_A1A2E0_CALLER_LAST_VA, 0xa196e8);
  assert.equal(RENDER_SHELL_HOST_A1A470_CALLER_COUNT, 2);
  assert.equal(RENDER_SHELL_HOST_A1A470_CALLER_FIRST_VA, 0x925dd9);
  assert.equal(RENDER_SHELL_HOST_A1A470_CALLER_LAST_VA, 0xa19b6c);
  assert.equal(RENDER_SHELL_HOST_A1A500_CALLER_COUNT, 28);
  assert.equal(RENDER_SHELL_HOST_A1A500_CALLER_FIRST_VA, 0xa18df5);
  assert.equal(RENDER_SHELL_HOST_A1A500_CALLER_LAST_VA, 0xb16fbb);
  /* Layout laws (a1a540/a1a580 shared 7-field table; PE stores). */
  assert.equal(RENDER_SHELL_A1A540_FIELD_COUNT, 7);
  assert.equal(RENDER_SHELL_A1A580_FIELD_COUNT, 7);
  assert.equal(RENDER_SHELL_A1A540_ALIGNMENT_OFF, 0x00);
  assert.equal(RENDER_SHELL_A1A540_MAX_CHARS_OFF, 0x04);
  assert.equal(RENDER_SHELL_A1A540_MODE_OFF, 0x08);
  assert.equal(RENDER_SHELL_A1A540_SCALE_OFF, 0x0c);
  assert.equal(RENDER_SHELL_A1A540_UNK10_OFF, 0x10);
  assert.equal(RENDER_SHELL_A1A540_UNK14_OFF, 0x14);
  assert.equal(RENDER_SHELL_A1A540_UNK18_OFF, 0x18);
  assert.equal(RENDER_SHELL_A1A540_MAX_CHARS_DEFAULT, 0xffff);
  assert.equal(RENDER_SHELL_A1A540_SCALE_DEFAULT_BITS, 0x3f800000);
  assert.equal(RENDER_SHELL_A1A540_UNK10_DEFAULT, 0xffffffff);
  /* Accessor law pins. */
  assert.equal(RENDER_SHELL_A1A580_ARG_OFF, 0x00);
  assert.equal(RENDER_SHELL_A1A5C0_DEST_OFF, 0x00);
  assert.equal(RENDER_SHELL_A1A5D0_DEST_OFF, 0x04);
  assert.equal(RENDER_SHELL_A1A5D0_WORD_MASK, 0xffff);
  assert.equal(RENDER_SHELL_A1A5E0_SRC_OFF, 0x04);
  assert.equal(RENDER_SHELL_A1A5E0_WORD_MASK, 0xffff);
  assert.equal(RENDER_SHELL_A1A5F0_CMP_OFF, 0x08);
  assert.equal(RENDER_SHELL_A1A5F0_CMP_VAL, 1);
  assert.equal(RENDER_SHELL_A1A540_EAX_WRITES, 1);
  assert.equal(RENDER_SHELL_A1A540_STACK_ARGS, 0);
  assert.equal(RENDER_SHELL_A1A540_THISCALL, 1);
  assert.equal(RENDER_SHELL_A1A580_STACK_ARGS, 1);
  assert.equal(RENDER_SHELL_A1A5C0_STACK_ARGS, 1);
  assert.equal(RENDER_SHELL_A1A5D0_STACK_ARGS, 1);
  assert.equal(RENDER_SHELL_A1A5E0_STACK_ARGS, 0);
  assert.equal(RENDER_SHELL_A1A5F0_STACK_ARGS, 0);
  /* Field-law fixed cases: idx 0..6 = PE store table; OOR -> 0
     (full-dword guard, NO uint8_t). Both ctors share the table. */
  const fieldDefs = [
    [0x00, 0x00000000],
    [0x04, 0x0000ffff],
    [0x08, 0x00000000],
    [0x0c, 0x3f800000],
    [0x10, 0xffffffff],
    [0x14, 0x00000000],
    [0x18, 0x00000000],
  ];
  for (let idx = 0; idx < fieldDefs.length; idx += 1) {
    const [off, def] = fieldDefs[idx];
    assert.equal(renderShellA1a540FieldOff(idx), off, `oracle a1a540 off ${idx}`);
    assert.equal(renderShellA1a540FieldDefault(idx), def, `oracle a1a540 def ${idx}`);
    assert.equal(renderShellA1a580FieldOff(idx), off, `oracle a1a580 off ${idx}`);
    assert.equal(renderShellA1a580FieldDefault(idx), def, `oracle a1a580 def ${idx}`);
    assert.equal(exp.isaac_render_shell_a1a540_field_off(idx) >>> 0, off);
    assert.equal(exp.isaac_render_shell_a1a540_field_default(idx) >>> 0, def);
    assert.equal(exp.isaac_render_shell_a1a580_field_off(idx) >>> 0, off);
    assert.equal(exp.isaac_render_shell_a1a580_field_default(idx) >>> 0, def);
  }
  for (const idx of [7, 8, 0x100, 0xffffffff]) {
    assert.equal(renderShellA1a540FieldOff(idx), 0, `oracle OOR off ${idx}`);
    assert.equal(renderShellA1a540FieldDefault(idx), 0, `oracle OOR def ${idx}`);
    assert.equal(renderShellA1a580FieldOff(idx), 0);
    assert.equal(renderShellA1a580FieldDefault(idx), 0);
    assert.equal(exp.isaac_render_shell_a1a540_field_off(idx) >>> 0, 0);
    assert.equal(exp.isaac_render_shell_a1a540_field_default(idx) >>> 0, 0);
    assert.equal(exp.isaac_render_shell_a1a580_field_off(idx) >>> 0, 0);
    assert.equal(exp.isaac_render_shell_a1a580_field_default(idx) >>> 0, 0);
  }
